WORK = Path(__file__).resolve().parent
IMAGE = 'sha256:d74eeac9a635390a49bc21bd49fccd973de707e2a53a76ac49b552b8712ec46f'
API_IMAGE = '701329f1cfe7b45f5b6d0cfe62daeae0edf6e1c00518158cb8555a815c224031'
WORKER_IMAGE = '7eafd5c9232ac9f8bfb2f6d1ab5eb4fa7ca37cc369bf92751616c90e29c76fa1'
