       '-o','UserKnownHostsFile='+str(ROOT/'.tmp/base-preprod-c1/oci-known-hosts'),
       '-o','StrictHostKeyChecking=yes','-o','BatchMode=yes','-o','ConnectTimeout=15',
       'opc@150.136.7.19']
GPG = 'C:/Program Files/Git/usr/bin/gpg.exe'
BASE_ENV = {k:v for k,v in os.environ.items() if not re.search(
    r'DATABASE|POSTGRES|^PG|CLERK|JWT|CLOUDINARY|RESEND|NOTIFICATION|EMAIL|E2E|TOKEN|SECRET|PASSWORD',k,re.I)}
RUN = secrets.token_hex(6)
REPORT = {'base':'5340f97bfd4a3fbc67b491bc50ff4b34bf1f6fef',
          'startedUtc':datetime.now(timezone.utc).isoformat(),'commands':[],'checks':[],
          'ownedContainers':[],'removedContainers':[],'qaFrozen':False,'qaResumed':False,
          'productionAccess':False,'push':False,'p3':False}
STAGE = 'preparacion'
OWNED = []
OWNED_NETWORKS = []
SOURCE = None
PG_ENV = None
PHRASE = None
DECRYPT_PHRASE = None
MODE = 'qa'
BASELINE_LEDGER = None
EXPECTED_VERSION_NUM = 170006
CUSTODY = Path('C:/KortekBackups/qa-m2-c3')
LOCAL_ROLLBACK_ARTIFACT = False
LAST_QUERY = None
PRIVATE_VALUES = []
GPG_HOME = None

def save():
    destination=WORK/'result.json'
    temporary=WORK/'result.json.tmp'
    temporary.write_text(json.dumps(REPORT,indent=2,ensure_ascii=True)+'\n',encoding='utf-8')
    temporary.replace(destination)

def emit(event, **fields):
    print(json.dumps({'event':event,**fields},ensure_ascii=True),flush=True)
    REPORT['event']=event
    save()

def sanitize_message(value):
    # No payloads, SQL DETAIL/CONTEXT, literals, credential values or command argv.
    text=str(value)
    for secret in PRIVATE_VALUES:
        if secret: text=text.replace(secret,'[privado]')
    if PG_ENV and PG_ENV.get('PGPASSWORD'): text=text.replace(PG_ENV['PGPASSWORD'],'[privado]')
    for secret in [PHRASE,DECRYPT_PHRASE]:
        if secret: text=text.replace(bytes(secret).decode('utf-8',errors='replace'),'[privado]')
    text=re.sub(r'(?:postgres(?:ql)?|https?|ssh)://[^\s]+','[direccion omitida]',text,flags=re.I)
    text=re.sub(r'(?i)(password|passphrase|token|secret|clave)\s*[:=]\s*[^\s,;]+',r'\1=[privado]',text)
    text=re.sub(r'"[^"\r\n]*"','[literal omitido]',text)
    text=re.sub("'[^'\r\n]*'",'[literal omitido]',text)
    text=re.sub(r'(?i)(Failing row contains).*',r'\1 [fila omitida]',text)
    text=re.sub(r'(?i)(DETAIL:.*Key.*?)=\([^\r\n]*\)',r'\1=([valor omitido])',text)
    return text

def failure_info(error, phase=None, event='parada'):
    frames=[{'file':Path(f.filename).name,'line':f.lineno,'function':f.name}
            for f in traceback.extract_tb(error.__traceback__)]
    message=sanitize_message(error).encode('utf-8')[:8192].decode('utf-8',errors='ignore')
    if isinstance(error,subprocess.TimeoutExpired): message='comando supero el timeout: '+str(error.timeout)+' s'
    if isinstance(error,subprocess.CalledProcessError): message='comando devolvio exit '+str(error.returncode)
    return {'event':event,'phase':phase or STAGE,'exceptionClass':type(error).__name__,
            'messageSanitized':message,'queryLabel':LAST_QUERY,'tracebackSanitized':frames}

def retain_failure(error, phase=None, event='parada'):
    item=failure_info(error,phase,event)
    REPORT['success']=False
    REPORT.setdefault('errors',[]).append(item)
    REPORT.setdefault('failure',item)
    try: save()
    except Exception as handler_error:
        REPORT['errors'].append(failure_info(handler_error,'persistencia-error','fallo-manejador'))
        # Fallback separado: no depende de save ni del emisor fallido.
        (WORK/'failure-fallback.json').write_text(json.dumps(REPORT,indent=2,ensure_ascii=True)+'\n',encoding='utf-8')
    return item

def report_failure(error):
    item=retain_failure(error)
    try: emit('parada',failure=item)
    except Exception as handler_error: retain_failure(handler_error,'manejador-error','fallo-manejador')

def safe_stderr(data):
    return sanitize_message(data.decode('utf-8',errors='replace')).encode('utf-8')[:8192].decode('utf-8',errors='ignore')

def command_record(args, code, stderr, label=None, error=None):
    redacted=sanitize_message(stderr.decode('utf-8',errors='replace')).encode('utf-8')
    safe=['--snapshot=<snapshot-en-memoria>' if x.startswith('--snapshot=') else sanitize_message(x) for x in args]
    frames=[]
    if error is not None:
        frames=failure_info(error)['tracebackSanitized']
    elif code:
        frames=[{'file':Path(f.filename).name,'line':f.lineno,'function':f.name}
                for f in traceback.extract_stack()[:-1]]
    item={'args':safe,'commandSanitized':safe,'exitCode':code,'label':label,'phase':STAGE,
          'stderrCompleteRedacted':redacted[:8192].decode('utf-8',errors='ignore'),
          'stderrTruncated':len(redacted)>8192,'stderrCapBytes':8192,
          'exceptionClass':type(error).__name__ if error is not None else 'ExternalCommandExit' if code else None,
          'tracebackSanitized':frames}
    REPORT['commands'].append(item);save()
    return item

def command_failure(label, code, stderr):
    REPORT['failureCommand']={'label':label,'exitCode':code,'messageSanitized':safe_stderr(stderr)}
    raise RuntimeError(str(label or 'comando-fallido')+'; exit='+str(code)+'; '+safe_stderr(stderr))

def spawn_pipe(args, **kwargs):
    try: process=subprocess.Popen(args,cwd=ROOT,stderr=subprocess.PIPE,**kwargs)
    except BaseException as error:
        command_record(args,None,b'',label='crear-proceso-pipe',error=error)
        raise
    errors=[]
    def drain():
        while True:
            part=process.stderr.read(8192)
            if not part: break
            errors.append(part)
    worker=threading.Thread(target=drain,daemon=True); worker.start()
    process.p2_errors=errors; process.p2_error_worker=worker
    process.p2_args=args;process.p2_recorded=False
    return process

def pipe_error(process):
    process.p2_error_worker.join(timeout=5)
    return b''.join(process.p2_errors)

def record_pipe(process,label):
    if not process.p2_recorded:
        command_record(process.p2_args,process.returncode,pipe_error(process),label)
        process.p2_recorded=True

def check(label, **fields):
    REPORT['checks'].append({'label':label,**fields})
    emit(label,**fields)

def run(args, data=None, env=None, timeout=120, expected=0, label=None, record=True):
    try:
        process=subprocess.Popen(args,cwd=ROOT,stdin=subprocess.PIPE if data is not None else subprocess.DEVNULL,
                                 stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env or BASE_ENV)
    except BaseException as error:
        command_record(args,None,b'',label,error=error)
        raise
    try:
        output,stderr=process.communicate(input=data,timeout=timeout)
    except BaseException as error:
        if process.poll() is None: process.kill()
        output,stderr=process.communicate(timeout=15)
        command_record(args,process.returncode,stderr,label,error=error)
        raise
    command_record(args,process.returncode,stderr,label)
    if expected is not None and process.returncode != expected:
        command_failure(label,process.returncode,stderr)
    return output

def docker(*args, **kwargs): return run(DOCKER+list(args),**kwargs)
def ssh(command, **kwargs): return run(SSH+[command],**kwargs)
def ident(value): return '"'+value.replace('"','""')+'"'
def literal(value): return "'"+str(value).replace("'","''")+"'"
def msys(path):
    s=Path(path).resolve().as_posix()
    if not re.match(r'^[A-Za-z]:/',s): raise RuntimeError('ruta-msys')
    return '/'+s[0].lower()+s[2:]
def erase(value):
    if isinstance(value,bytearray): value[:]=b'\0'*len(value)

def start(name, server=False, ca=False, api_access=False):
    network='none' if server else 'bridge'
    if api_access:
        network='p2-isolated-'+RUN
        docker('network','create','--driver','bridge','--opt','com.docker.network.bridge.enable_ip_masquerade=false',network,label='red-propia-sin-NAT-saliente')
        OWNED_NETWORKS.append(network)
    args=['run','--detach','--rm','--name',name,'--network',network,
          '--read-only','--cpus','1','--memory','1536m' if server else '768m',
          '--pids-limit','128','--tmpfs','/tmp:rw,size=64m',
          '--tmpfs','/var/run/postgresql:rw,size=16m',
          '--tmpfs','/var/lib/postgresql/data:rw,size=1024m']
    if api_access: args+=['--publish','127.0.0.1::5432']
    if ca:
        args+=['--mount','type=bind,source='+str(ROOT/'ops/oci-free-backup/prod-ca-2021.crt')+
               ',target=/tmp/qa-ca.crt,readonly']
    startup_env=BASE_ENV
    if server:
        if api_access:
            startup_env=dict(BASE_ENV,POSTGRES_PASSWORD=secrets.token_hex(32))
            args+=['--env','POSTGRES_HOST_AUTH_METHOD=scram-sha-256','--env','POSTGRES_PASSWORD']
        else:args+=['--env','POSTGRES_HOST_AUTH_METHOD=trust']
        args+=[IMAGE,'postgres','-c','listen_addresses=*' if api_access else 'listen_addresses=127.0.0.1']
    else: args+=['--entrypoint','sleep',IMAGE,'infinity']
    docker(*args,env=startup_env,label='crear-contenedor-propio')
    OWNED.append(name); REPORT['ownedContainers'].append(name)
    if server:
        for _ in range(60):
            run(DOCKER+['exec',name,'pg_isready','-U','postgres'],expected=None,label='esperar-PG17-propio')
            if REPORT['commands'][-1]['exitCode']==0: break
            time.sleep(.5)
        else: raise RuntimeError('PG17-aislado-no-listo')
    return name

def local_sql(container, sql, database='postgres', role='postgres', expected=0):
    if container not in OWNED: raise RuntimeError('destino-local-no-propio')
    return docker('exec','-i','-e','PGCLIENTENCODING=UTF8',container,'psql','-X','-qAt','-v','ON_ERROR_STOP=1',
                  '-U',role,'-d',database,data=sql.encode('utf-8'),expected=expected,
                  label='sql-aislado').decode('utf-8').strip()

class Reader:
    def __init__(self, client):
        keys=['PGPASSWORD','PGHOST','PGPORT','PGUSER','PGDATABASE','PGSSLMODE','PGSSLROOTCERT','PGOPTIONS','PGAPPNAME','PGCLIENTENCODING']
        opts=sum((['-e',k] for k in keys),[])
        args=DOCKER+['exec','-i']+opts+[client,'psql','-X','-qAt','-v','ON_ERROR_STOP=1']
        try:
            self.proc=subprocess.Popen(args,cwd=ROOT,env=PG_ENV,stdin=subprocess.PIPE,
                                       stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,encoding='utf-8',errors='strict')
        except BaseException as error:
            command_record(args,None,b'',label='crear-reader',error=error)
            raise
        import io
        self.proc.stdin=io.TextIOWrapper(self.proc.stdin.detach(),encoding='utf-8',newline='\n',write_through=True)
        self.lines=queue.Queue()
        self.stderr=[]
        self.args=args;self.recorded=False
        def error_pump():
            for line in self.proc.stderr:
                self.stderr.append(line)
        self.error_thread=threading.Thread(target=error_pump,daemon=True);self.error_thread.start()
        def pump():
            for line in self.proc.stdout: self.lines.put(line.rstrip('\r\n'))
            self.lines.put(None)
        threading.Thread(target=pump,daemon=True).start()
        try: self.q("BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL statement_timeout='120s'")
        except BaseException:
            self.kill()
            raise
    def q(self, sql, label='consulta-scalar'):
        global LAST_QUERY
        LAST_QUERY=label
        sql=sql.replace('\r\n','\n')
        if '\r' in sql: raise ValueError('bare CR rejected before SQL Reader transmission')
        end='P2_END_'+secrets.token_hex(8)
        self.proc.stdin.write(sql+";\nSELECT '"+end+"';\n"); self.proc.stdin.flush()
        rows=[]
        while True:
            line=self.lines.get(timeout=150)
            if line is None:
                self.proc.wait(timeout=15);self.record()
                raise RuntimeError('reader-fuente-fallo; '+safe_stderr(''.join(self.stderr).encode('utf-8')))
            if line==end: return rows
            if line: rows.append(line)
    def json(self, sql, label=None):
        label=label or {LEDGER_SQL:'ledger-tecnico',CATALOG_SQL:'catalogo',ROLE_SQL:'roles',COUNTS_SQL:'conteos'}.get(sql,'login-readonly')
        return json.loads('\n'.join(self.q(sql,label=label)))
    def close(self):
        if self.proc.poll() is None:
            self.q('COMMIT'); self.proc.stdin.close()
            self.proc.wait(timeout=15)
        self.record()
        if self.proc.returncode!=0: raise RuntimeError('reader-fuente-exit; '+safe_stderr(''.join(self.stderr).encode('utf-8')))
    def kill(self):
        if self.proc.poll() is None: self.proc.kill(); self.proc.wait(timeout=15)
        self.record()
    def record(self):
        if not self.recorded:
            self.error_thread.join(timeout=5)
            command_record(self.args,self.proc.returncode,''.join(self.stderr).encode('utf-8'),'reader-fuente-RR-RO')
            self.recorded=True

NativeReader=Reader

def local_census(container,database='postgres',catalog=None):
    global PG_ENV
    if container not in OWNED:raise RuntimeError('censo-no-propio')
    prior=PG_ENV
    PG_ENV=dict(BASE_ENV,PGHOST='/var/run/postgresql',PGPORT='5432',PGUSER='postgres',
      PGDATABASE=database,PGSSLMODE='disable',PGCLIENTENCODING='UTF8',
      PGOPTIONS='-c default_transaction_read_only=on -c statement_timeout=120000',PGAPPNAME='p2-local-census')
    try:reader=NativeReader(container)
    finally:PG_ENV=prior
    try:return census(lambda sql:'\n'.join(reader.q(sql)),catalog=catalog)
    finally:reader.close()

def dump_args(client, snapshot, *extra):
    keys=['PGPASSWORD','PGHOST','PGPORT','PGUSER','PGDATABASE','PGSSLMODE','PGSSLROOTCERT','PGOPTIONS','PGAPPNAME','PGCLIENTENCODING']
    return DOCKER+['exec']+sum((['-e',k] for k in keys),[])+[
        client,'pg_dump','--schema=public','--format=custom','--no-owner','--no-privileges',
        '--encoding=UTF8','--snapshot='+snapshot]+list(extra)

def infra():
    cmd='systemctl show kortek-api-staging kortek-email-worker-staging --property=Id,ActiveState,SubState,MainPID,NRestarts; XDG_RUNTIME_DIR=/run/user/1000 podman inspect --format "{{.Name}} {{.Image}} {{.State.Status}}" kortek-api-staging kortek-email-worker-staging; sudo -n sha256sum /etc/kortek-api-staging/runtime-env /usr/local/libexec/kortek-api-staging-run.sh /usr/local/libexec/kortek-worker-staging-run.sh /etc/systemd/system/kortek-api-staging.service /etc/systemd/system/kortek-email-worker-staging.service'
    value=ssh(cmd,label='estado-seguro-QA').decode('utf-8')
    if API_IMAGE not in value or WORKER_IMAGE not in value or value.count('ActiveState=active')!=2 or value.count('SubState=running')!=2:
        raise RuntimeError('servicios-imagenes-difieren-P0')
    if value.count('NRestarts=0')!=2: raise RuntimeError('reinicios-inesperados')
    if set(re.findall(r'^MainPID=(\d+)$',value,re.M))!={'673295','575989'}: raise RuntimeError('PID-difiere-P0')
    prior=json.loads((ROOT/'docs/quality/evidence/m2-c3-p2/p2-segundo-intento.json').read_text(encoding='utf-8'))
    observed=dict((path,digest) for digest,path in re.findall(r'^([0-9a-f]{64})\s+(\S+)$',value,re.M))
    if observed!=prior['hashesArchivosQa']: raise RuntimeError('archivos-QA-difieren-baseline')
    return value

def effective():
    prior=json.loads((ROOT/'docs/quality/evidence/m2-c3-p2/p2-segundo-intento.json').read_text(encoding='utf-8'))
    code=prior['effectiveReaderCode']
    value=json.loads(ssh('XDG_RUNTIME_DIR=/run/user/1000 podman exec -i --workdir /srv/kortek/apps/api kortek-api-staging node',
                         data=code.encode('utf-8'),label='destino-release-efectivo-RO').decode('utf-8'))
    for key in ['releaseMatchesP0','databaseRoleMatches','databaseMatches','qaUserMatches','qaEndpointMatches','effectiveServerMatchesQaDns','deployEnvironmentMatches','publicBookingOpen']:
        if value.get(key) is not True: raise RuntimeError('destino-release-QA-no-coincide')
    return value

def request_phrase(kind):
    global DECRYPT_PHRASE
    emit('prompt-frase',kind=kind)
    line=sys.stdin.buffer.readline()
    if not line: raise RuntimeError('prompt-cerrado')
    value=bytearray(line.rstrip(b'\r\n')); line=None
    if not value: raise RuntimeError('frase-vacia')
    if kind=='cifrar-doble-confirmacion':
        second_line=sys.stdin.buffer.readline()
        second=bytearray(second_line.rstrip(b'\r\n')); second_line=None
        same=bool(second) and secrets.compare_digest(value,second)
        DECRYPT_PHRASE=second if same else None
        if not same: erase(second)
        second=None
        if not same:
            erase(value)
            raise RuntimeError('frases-no-coinciden-antes-dump')
    PRIVATE_VALUES.append(bytes(value).decode('utf-8'))
    return value

def gpg_args(phrase, path, encrypt=True):
    global GPG_HOME
    if GPG_HOME is None:
        home=ROOT/'.tmp'/('kh-'+RUN[:6])
        if ROOT not in home.resolve().parents or home.exists(): raise RuntimeError('homedir-GPG-no-propio')
        if len(msys(home)+'/S.gpg-agent')>90: raise RuntimeError('socket-GPG-supera90')
        home.mkdir();GPG_HOME=home
        REPORT['ownGpgHome']={'path':str(home),'socketCharacters':len(msys(home)+'/S.gpg-agent')}
    home=GPG_HOME
    args=[GPG,'--no-options','--homedir',msys(home),'--no-symkey-cache','--batch',
          '--pinentry-mode','loopback','--passphrase-fd','0']
    return args+(['--symmetric','--cipher-algo','AES256','--output',msys(path)] if encrypt else ['--decrypt',msys(path)])

def encrypt_data(phrase, data, dest):
    # GPG consume la primera línea del stdin como frase; el resto es el payload.
    temporary=dest.with_suffix(dest.suffix+'.partial')
    try:
        run(gpg_args(phrase,temporary),data=bytes(phrase)+b'\n'+data,label='cifrado-AES256-stdin-anonimo')
        temporary.replace(dest)
    finally:
        if temporary.exists(): temporary.unlink()

def decrypt_data(phrase, path):
    return run(gpg_args(phrase,path,False),data=bytes(phrase)+b'\n',label='descifrado-stdin-anonimo')

CATALOG_SQL = r"""SELECT json_build_object(
 'tables',(SELECT coalesce(json_agg(x ORDER BY x.name),'[]') FROM
   (SELECT c.relname AS name,pg_get_userbyid(c.relowner) AS owner FROM pg_class c
    WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p')) x),
 'columns',(SELECT coalesce(json_agg(x ORDER BY x.table_name,x.position),'[]') FROM
   (SELECT c.relname AS table_name,a.attname AS name,a.attnum AS position,
     format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS not_null,
     a.attidentity AS identity,a.attgenerated AS generated,
     pg_get_expr(d.adbin,d.adrelid) AS default_expr
    FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
    LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
    WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p')
      AND a.attnum>0 AND NOT a.attisdropped) x),
 'constraints',(SELECT coalesce(json_agg(x ORDER BY x.table_name,x.name),'[]') FROM
   (SELECT c.relname AS table_name,k.conname AS name,k.contype AS type,k.convalidated AS validated,
      pg_get_constraintdef(k.oid,true) AS definition FROM pg_constraint k
    JOIN pg_class c ON c.oid=k.conrelid WHERE c.relnamespace='public'::regnamespace) x),
 'indexes',(SELECT coalesce(json_agg(x ORDER BY x.table_name,x.name),'[]') FROM
   (SELECT tablename AS table_name,indexname AS name,indexdef AS definition
      FROM pg_indexes WHERE schemaname='public') x),
 'triggers',(SELECT coalesce(json_agg(x ORDER BY x.table_name,x.name),'[]') FROM
   (SELECT c.relname AS table_name,t.tgname AS name,t.tgenabled AS enabled,
      pg_get_triggerdef(t.oid,true) AS definition FROM pg_trigger t
    JOIN pg_class c ON c.oid=t.tgrelid
    WHERE c.relnamespace='public'::regnamespace AND NOT t.tgisinternal) x),
 'functions',(SELECT coalesce(json_agg(x ORDER BY x.signature),'[]') FROM
   (SELECT format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) AS signature,
       pg_get_userbyid(p.proowner) AS owner,pg_get_functiondef(p.oid) AS definition
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND NOT EXISTS(SELECT 1 FROM pg_depend d
      WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')) x),
 'types',(SELECT coalesce(json_agg(x ORDER BY x.name),'[]') FROM
   (SELECT t.typname AS name,pg_get_userbyid(t.typowner) AS owner,
       (SELECT json_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid) AS labels
    FROM pg_type t WHERE t.typnamespace='public'::regnamespace AND t.typtype='e') x),
 'schemaOwner',(SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='public'),
 'extensions',(SELECT json_agg(json_build_object('name',e.extname,'version',e.extversion,'schema',e.extnamespace::regnamespace::text) ORDER BY e.extname)
    FROM pg_extension e WHERE e.extnamespace='public'::regnamespace)
)"""

ROLE_SQL = r"""SELECT json_build_object(
 'attributes',(SELECT json_agg(x ORDER BY x.rolname) FROM
   (SELECT rolname,rolcanlogin,rolinherit,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls
      FROM pg_roles WHERE rolname IN ('kortek_runtime','kortek_migrator','kortek_backup')) x),
 'memberships',(SELECT coalesce(json_agg(x ORDER BY x.member,x.role),'[]') FROM
   (SELECT pg_get_userbyid(member) AS member,pg_get_userbyid(roleid) AS role,admin_option
     FROM pg_auth_members WHERE member IN
       (SELECT oid FROM pg_roles WHERE rolname IN ('kortek_runtime','kortek_migrator','kortek_backup'))) x),
 'tablePrivileges',(SELECT json_agg(x ORDER BY x.role,x.table_name,x.privilege) FROM
   (SELECT r.rolname AS role,t.tablename AS table_name,p.privilege,
        has_table_privilege(r.oid,format('%I.%I','public',t.tablename),p.privilege) AS allowed
      FROM pg_roles r CROSS JOIN pg_tables t
      CROSS JOIN (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(privilege)
      WHERE r.rolname IN ('kortek_runtime','kortek_migrator','kortek_backup') AND t.schemaname='public') x),
 'schemaPrivileges',(SELECT json_agg(x ORDER BY x.role,x.privilege) FROM
   (SELECT r.rolname AS role,p.privilege,has_schema_privilege(r.oid,'public',p.privilege) AS allowed
     FROM pg_roles r CROSS JOIN (VALUES ('USAGE'),('CREATE')) p(privilege)
     WHERE r.rolname IN ('kortek_runtime','kortek_migrator','kortek_backup')) x),
 'functionPrivileges',(SELECT coalesce(json_agg(x ORDER BY x.role,x.signature),'[]') FROM
   (SELECT r.rolname AS role,format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) AS signature,
      has_function_privilege(r.oid,p.oid,'EXECUTE') AS allowed
    FROM pg_roles r CROSS JOIN pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND r.rolname IN ('kortek_runtime','kortek_migrator','kortek_backup')
      AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')) x),
 'defaults',(SELECT coalesce(json_agg(x ORDER BY x.owner,x.namespace,x.kind,x.grantee,x.privilege),'[]') FROM
   (SELECT pg_get_userbyid(d.defaclrole) AS owner,
      CASE WHEN d.defaclnamespace=0 THEN '' ELSE (SELECT nspname FROM pg_namespace WHERE oid=d.defaclnamespace) END AS namespace,
      d.defaclobjtype AS kind,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,
      a.privilege_type AS privilege,a.is_grantable AS grantable
    FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a
    WHERE d.defaclrole IN (SELECT oid FROM pg_roles WHERE rolname IN ('kortek_runtime','kortek_migrator','kortek_backup'))
      AND (d.defaclnamespace=0 OR d.defaclnamespace='public'::regnamespace)) x)
)"""

