import hashlib

def normalized_sql(data):
    result=data.replace(b'\r\n',b'\n')
    if b'\r' in result:
        raise ValueError('SQL contains a bare CR; rejected before transmission')
    return result

def install(m):
    original=m.docker
    def guarded(*args,**kwargs):
        if 'psql' in args and kwargs.get('data') is not None:
            data=normalized_sql(kwargs['data'])
            m.REPORT.setdefault('sqlStdinByteChecks',[]).append({'label':kwargs.get('label'),'sha256Sent':hashlib.sha256(data).hexdigest(),'CRcount':data.count(b'\r'),'bytes':len(data)})
            kwargs['data']=data
        return original(*args,**kwargs)
    m.docker=guarded

